## Connection Validation with Dynamic Ports

The validation system must consider dynamic ports when checking connection compatibility.

### Port Lookup Strategy

Validation merges static and dynamic ports:

```mermaid
graph TB
    subgraph "Source Port Lookup"
        S1["Get component.outputs (static)"]
        S2["Get node.data.dynamicOutputs"]
        S3["Merge arrays"]
        S4["Add virtual 'tools' port if tool mode"]
    end

    subgraph "Target Port Lookup"
        T1["Get component.inputs (static)"]
        T2["Get node.data.dynamicInputs"]
        T3["Merge arrays"]
    end

    subgraph "Validation"
        V1["Find sourceHandle in merged outputs"]
        V2["Find targetHandle in merged inputs"]
        V3["Check type compatibility"]
    end

    S1 --> S3
    S2 --> S3
    S3 --> S4
    S4 --> V1

    T1 --> T3
    T2 --> T3
    T3 --> V2

    V1 --> V3
    V2 --> V3
```

**Implementation:**

```typescript
// Source port lookup with dynamic outputs
let sourceOutputs = (sourceNode.data as any).dynamicOutputs || 
                    sourceComponent.outputs || 
                    [];

// Tool mode adds virtual 'tools' port
const sourceConfig = sourceNode.data.config as any;
if (sourceConfig?.isToolMode || sourceConfig?.mode === 'tool') {
  sourceOutputs = [
    ...sourceOutputs,
    {
      id: 'tools',
      label: 'Tool Export',
      connectionType: { kind: 'contract', name: 'mcp.tool' },
    },
  ];
}

// Target port lookup with dynamic inputs
const targetInputs = (targetNode.data as any).dynamicInputs || 
                     targetComponent.inputs || 
                     [];

// Find ports
const sourcePort = sourceOutputs.find((p: any) => p.id === sourceHandle);
const targetPort = targetInputs.find((p: any) => p.id === targetHandle);
```

