For backwards compatibility, the validation system can generate dynamic outputs for Entry Point nodes that don't yet have `dynamicOutputs` populated:

```typescript
if (sourceComponent.id === 'core.workflow.entrypoint' &&
    !(sourceNode.data as any).dynamicOutputs) {
  const runtimeInputsParam = sourceNodeData.config?.params?.runtimeInputs;

  if (runtimeInputsParam) {
    const runtimeInputs = typeof runtimeInputsParam === 'string'
      ? JSON.parse(runtimeInputsParam)
      : runtimeInputsParam;

    sourceOutputs = [
      ...sourceOutputs,
      ...runtimeInputs.map((input: any) => {
