## Specialized Request Handling

### Server-Sent Events (SSE)

Execution streams use a custom `FetchEventSource` that supports authentication headers:

```mermaid
sequenceDiagram
    participant Component
    participant api
    participant FetchEventSource
    participant Backend

    Component->>api: api.executions.stream(runId, options)
    api->>api: await getFreshClerkToken()
    api->>api: Build auth headers
    api->>FetchEventSource: new FetchEventSource(url, {headers})

    loop Event Stream
        Backend->>FetchEventSource: SSE: data: {...}
        FetchEventSource->>Component: EventSource.onmessage()
    end
```

**Sources:** [frontend/src/services/api.ts:810-863]()

### Implementation

```typescript
stream: async (
  executionId: string,
  options?: {
    cursor?: string;
    temporalRunId?: string;
    terminalCursor?: string;
    logCursor?: string;
  },
): Promise<EventSource> => {
  const { FetchEventSource } = await import('@/utils/sse-client');

  const storeState = useAuthStore.getState();
  let token = storeState.token;
  const organizationId = storeState.organizationId;

  // For Clerk auth, fetch a fresh token
  if (storeState.provider === 'clerk') {
    try {
      const freshToken = await getFreshClerkToken();
      if (freshToken) {
        token = freshToken;
        storeState.setToken(freshToken);
      }
    } catch (_error) {
      // Ignore token fetch errors for SSE
    }
  }

  // Build URL with query params
  const params = new URLSearchParams();
  if (options?.cursor) params.set('cursor', options.cursor);
  // ... other params
  const url = `${API_V1_URL}/workflows/runs/${executionId}/stream${query ? `?${query}` : ''}`;

  // Build auth headers
  const headers: Record<string, string> = {};
  if (storeState.provider === 'local' && storeState.adminUsername && storeState.adminPassword) {
    const credentials = btoa(`${storeState.adminUsername}:${storeState.adminPassword}`);
    headers['Authorization'] = `Basic ${credentials}`;
  } else if (token && token.trim().length > 0) {
    headers['Authorization'] = token.startsWith('Bearer ') ? token : `Bearer ${token}`;
  }
  if (organizationId) {
    headers['X-Organization-Id'] = organizationId;
  }

  return new FetchEventSource(url, { headers });
}
```

